// pwPgxPinned attaches each pgx cell's pinned answers.
func pwPgxPinned(cells []pwPgxCell) []pwPgxCell {
	pins := map[string]pwPgxCell{
		"1410/$1 = n + f float64":      {want: "fields=23 rows=[1 ; 2]"},
		"1410/$1 = n + num float64":    {want: "fields=23 rows=[2]"},
		"1410/insert 2.5 into integer": {want: "fields= rows=[] stored=[2]", wantExec: "ERR 22P02"},
		"1410/select int64":            {want: "ERR failed to encode args[0]: unable to encode 7 into text format for text (OID 25): cannot find encode plan", wantExec: "fields=25 rows=[7]"},
		"1410/limit int64":             {want: "fields=23 rows=[1 ; 2]"},
		"1410/limit int":               {want: "fields=23 rows=[1 ; 2]"},
		"1410/offset int":              {want: "fields=23 rows=[4 ; 5 ; 10]"},
		"n = int64":                    {want: "fields=23 rows=[1]"},
		"n = float64 7.0":              {want: "fields=23 rows=[1]"},
		"insert 2.0 into integer":      {want: "fields= rows=[] stored=[2]"},
		"insert time into date":        {want: "fields= rows=[] stored=[2024-03-04]"},
		"select float64":               {want: "ERR failed to encode args[0]: unable to encode 2.5 into text format for text (OID 25): cannot find encode plan", wantExec: "fields=25 rows=[2.5]"},
		"select string":                {want: "fields=25 rows=[abc]"},
		"select $1 + 1 int":            {want: "fields=20 rows=[3]", pg: "fields=23 rows=[3]", row: "parameters-pgwire r12: integer arithmetic declares bigint here"},
		"select $1 + 1 negative int":   {want: "fields=20 rows=[-1]", pg: "fields=23 rows=[-1]", row: "parameters-pgwire r12: integer arithmetic declares bigint here"},
		"1426/d = time not midnight":   {want: "fields=23 rows=[1]"},
		"1426/d = time midnight":       {want: "fields=23 rows=[1]"},
		"1426/d < time":                {want: "fields=23 rows=[3 ; 10]"},
		"1426/d IN (time, time)":       {want: "fields=23 rows=[1 ; 10]"},
		"ts = time":                    {want: "fields=23 rows=[1]"},
		"lag int":                      {want: "fields=23,23 rows=[1|NULL ; 2|7 ; 3|14 ; 4|2 ; 5|3 ; 10|NULL]"},
		"s = string":                   {want: "fields=23 rows=[1]"},
		"num = float64":                {want: "fields=23 rows=[1]"},
		"f = int":                      {want: "fields=23 rows=[4]"},
		"u = string":                   {want: "fields=23 rows=[1]"},
		"bo = bool":                    {want: "fields=23 rows=[1 ; 3 ; 10]"},
		"n IN (SELECT $1)":             {want: "fields=23 rows=[1]", pg: "ERR 42883", row: "parameters-pgwire r6: a FROM-less subquery's parameter takes the comparison's type"},
	}
	for i, c := range cells {
		pin, ok := pins[c.name]
		if !ok {
			panic("pgx cell without a pin: " + c.name)
		}
		cells[i].want, cells[i].wantExec, cells[i].pg = pin.want, pin.wantExec, pin.pg
	}
	return cells
}
